--- 刷新成员立绘
---@param groupId any
function HomelandCheckInCardImgTeam:Refresh(groupId)
    self.groupId = groupId
    -- 刷新显示
    local vo = self.comp:GetGroupVo(groupId)
    if isNull(vo) then
        printError(string.format("没有找到groupId %d", groupId))
        return
    end

    -- 组员id列表
    local membersIdList = vo.members
    
    if isNull(self.membersMap) then
        -- 查找对应组员的预制体
        self.membersMap = self:FindCardImgPrefab(self.controller.gameObject.transform, membersIdList)
    end

    -- 设置组员的checkIn状态颜色
    self:SetCardImgColor(membersIdList)
end

--- 查找对应组员的预制体
---@param root any
---@param membersIdList any
function HomelandCheckInCardImgTeam:FindCardImgPrefab(root, membersIdList)
    local membersMap = {}
    local tf = root
    local count = tf.childCount
    for i = 1, count, 1 do
        local ttf = tf:Find("Role"..i)
        if isNotNull(ttf) then
            local child = ttf:GetChild(0)
            if isNotNull(child) then
                for i, memberId in ipairs(membersIdList) do
                    if string.contains(child.name, tostring(memberId), true) then
                        membersMap[memberId] = { go = child.gameObject }
                    end
                end
            end
        end
    end
    return membersMap
end

--- 设置组员的checkIn状态颜色
---@param membersIdList any
function HomelandCheckInCardImgTeam:SetCardImgColor(membersIdList)
    for i, memberId in ipairs(membersIdList) do
        local hasCheckIned = self.comp:HasMemberCheckIned(self.groupId, memberId)
        local color = hasCheckIned and Color.white or XLuaUtils.HexToColor('#666666')
        local data = self.membersMap[memberId]
        if isNotNull(data) then
            local go = data.go
            if isNotNull(go) then
                local gradientComp = go:GetComponent(typeof(Gradient2))
                if isNotNull(gradientComp) then
                    gradientComp.enabled = hasCheckIned
                end

                local image = go:GetComponent(typeof(Image))
                if isNotNull(image) then
                    image.color = color
                end
            end
        end
    end
end

return HomelandCheckInCardImgTeam